Value.Calculation:
Let (
  [
    raw = GetField ( "FOCUS::g_wv_module_index" )
  ] ;
  Case (
    IsEmpty ( raw ) ; 62 ;
    GetAsNumber ( raw )
  )
)

Let (
  [
    base = $_context_json ;
    valid = EvaluationError ( JSONFormatElements ( base ) ) = 0 ;
    action_count = GetAsNumber ( GetField ( "FOCUS::g_wv_action_count" ) ) ;
    action_type = GetAsText ( GetField ( "FOCUS::g_wv_action_type" ) ) ;
    action_status = GetAsText ( GetField ( "FOCUS::g_wv_action_status" ) )
  ] ;
  Case (
    not valid ; base ;
    JSONSetElement ( base
      ; [ "__wv.source" ; "article_02_demo" ; JSONString ]
      ; [ "actions.count" ; action_count ; JSONNumber ]
      ; [ "actions.last_type" ; action_type ; JSONString ]
      ; [ "actions.status" ; Case (
          IsEmpty ( action_status ) ; "Waiting for an action" ; action_status
        ) ; JSONString ]
    )
  )
)

Case (
  JSONFormatElements ( $_context_json ) = "?" ;
    "Build context failed: the framework script returned invalid JSON." ;
  "Context built for module " & $_index &
    If ( not IsEmpty ( $_movie_id ) ; " | movie_id " & $_movie_id ; "" ) &
    If ( not IsEmpty ( $_genre_id ) ; " | genre_id " & $_genre_id ; "" )
)
